33	            --font-display: 'Clash Display', sans-serif;
34	            --font-body: 'Satoshi', sans-serif;
35	            --title-size: clamp(2rem, 6vw, 5rem);
36	            --subtitle-size: clamp(0.875rem, 2vw, 1.25rem);
37	            --body-size: clamp(0.75rem, 1.2vw, 1rem);
