            border: 1px solid var(--border-subtle);
            border-radius: 10px;
            padding: clamp(0.6rem, 1.2vw, 1rem);
            display: flex;
            flex-direction: column;
            gap: clamp(0.2rem, 0.5vh, 0.4rem);
