        .deploy-metric-context {
            font-size: var(--tiny-size);
            color: var(--text-secondary);
            margin-top: clamp(0.15rem, 0.3vh, 0.3rem);
            line-height: 1.3;
        }

        .deploy-throughput-chart {
            display: flex;
            align-items: flex-end;
            gap: clamp(0.4rem, 0.8vw, 0.6rem);
            height: clamp(80px, 15vh, 140px);
            padding: clamp(0.5rem, 1vw, 0.8rem);
            background: var(--bg-surface);
            border-radius: 10px;
            border: 1px solid var(--border-subtle);
            max-width: min(95vw, 800px);
        }

        .throughput-bar-group {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: clamp(0.1rem, 0.2vh, 0.2rem);
            height: 100%;
            justify-content: flex-end;
        }

        .throughput-bar {
            width: 100%;
            border-radius: 4px 4px 0 0;
            position: relative;
            min-height: 4px;
            transition: height 1s var(--ease-out-expo);
        }

        .throughput-bar-val {
            position: absolute;
            top: -1.3em;
            left: 50%;
            transform: translateX(-50%);
            font-family: var(--font-mono);
            font-size: var(--tiny-size);
            font-weight: 600;
            white-space: nowrap;
        }

        .throughput-bar-label {
            font-size: calc(var(--tiny-size) * 0.9);
            color: var(--text-dim);
            text-align: center;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 100%;
        }

        .deploy-note {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
        }

        .deploy-note strong { color: var(--accent-amber); }

        /* ===========================================
           SLIDE 9: KEY TAKEAWAYS
           =========================================== */
        .takeaways-slide .slide-content {
            gap: clamp(0.5rem, 1.2vh, 1rem);
        }

        .takeaway-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: clamp(0.4rem, 1vw, 0.7rem);
            max-width: min(95vw, 850px);
        }

        .takeaway-item {
            background: var(--bg-surface);
            border: 1px solid var(--border-subtle);
            border-radius: 10px;
            padding: clamp(0.5rem, 1.2vw, 0.9rem);
            display: flex;
            gap: clamp(0.3rem, 0.8vw, 0.6rem);
            align-items: flex-start;
            transition: border-color 0.3s ease;
        }

        .takeaway-item:hover {
            border-color: var(--border-accent);
        }

        .takeaway-item.full-width {
            grid-column: 1 / -1;
        }

        .takeaway-icon {
            font-size: clamp(1rem, 2vw, 1.5rem);
            flex-shrink: 0;
            line-height: 1;
        }

        .takeaway-text {
            flex: 1;
        }

        .takeaway-title {
            font-family: var(--font-display);
            font-size: clamp(0.75rem, 1.2vw, 1rem);
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: clamp(0.1rem, 0.2vh, 0.15rem);
        }

        .takeaway-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
            line-height: 1.35;
        }

        .takeaway-cta {
            text-align: center;
            font-size: var(--small-size);
            color: var(--text-dim);
        }

        .takeaway-cta a {
            color: var(--accent-teal);
            text-decoration: none;
            font-weight: 600;
        }
    </style>
</head>
