            <div class="ram-comparison reveal-scale" style="transition-delay: 0.2s;">
                <div class="ram-bar-group">
                    <div class="ram-bar" style="background: var(--accent-teal); height: clamp(12px, 2vh, 20px);">
                        <span class="ram-bar-value" style="color: var(--accent-teal);">0.8 GB</span>
