                <div class="arch-stage" style="border-color: var(--border-accent);">
                    <div class="arch-stage-icon">⚡</div>
                    <div class="arch-stage-title">Pixel Shuffle</div>
                    <div class="arch-stage-desc">Space-to-depth compresses visual tokens by r²</div>
                </div>
                <div class="arch-arrow">→</div>
                <div class="arch-stage">
                    <div class="arch-stage-icon">🔗</div>
                    <div class="arch-stage-title">Linear Projection</div>
                    <div class="arch-stage-desc">Maps to language model input space</div>
                </div>
                <div class="arch-arrow">→</div>
