    <section class="slide compute-slide" data-slide="4">
        <div class="slide-content">
            <span class="tag reveal">Finding 1</span>
            <h2 class="reveal">Smaller Vision Encoders Outperform Larger Ones in Compact VLMs</h2>

            <div class="compute-comparison reveal" style="transition-delay: 0.2s;">
                <div class="compute-config winner">
