                        <div class="compute-bar lm" style="width: 55%;">SmolLM2 · 135M</div>
                    </div>
                    <div class="compute-bar-legend">
                        <span class="legend-item"><span class="legend-dot" style="background:var(--accent-blue)"></span> Vision Encoder: 93M</span>
                        <span class="legend-item"><span class="legend-dot" style="background:var(--accent-purple)"></span> Language Model: 135M</span>
                        <span style="color:var(--text-dim)">Total: 228M</span>
                    </div>
                </div>
                <div class="compute-config loser">
                    <div class="compute-config-header">
                        <span class="compute-config-label">Config B — Oversized Encoder</span>
                        <span class="compute-config-result">✗ Worse Performance</span>
                    </div>
                    <div class="compute-bars">
                        <div class="compute-bar encoder" style="width: 72%;">SigLIP-SO400M · 428M</div>
                        <div class="compute-bar lm" style="width: 24%;">SmolLM2 · 135M</div>
                    </div>
                    <div class="compute-bar-legend">
                        <span class="legend-item"><span class="legend-dot" style="background:var(--accent-blue)"></span> Vision Encoder: 428M</span>
                        <span class="legend-item"><span class="legend-dot" style="background:var(--accent-purple)"></span> Language Model: 135M</span>
                        <span style="color:var(--text-dim)">Total: 563M</span>
                    </div>
                </div>
            </div>

            <p class="compute-finding reveal" style="transition-delay: 0.35s;">
                <strong>Insight:</strong> Only at 1.7B LM scale does the larger encoder justify its 10% parameter overhead. For compact models, a smaller encoder frees budget for the language model.
            </p>
        </div>
        <span class="slide-number">04 / 09</span>
    </section>

    <!-- =========================================================
         SLIDE 5: TOKEN COMPRESSION
         ========================================================= -->
    <section class="slide token-slide" data-slide="5">
        <div class="slide-content">
            <span class="tag reveal">Finding 3</span>
            <h2 class="reveal">Aggressive Pixel Shuffle (r=4) Cuts Visual Tokens 16×</h2>

            <div class="pixel-shuffle-demo reveal-scale" style="transition-delay: 0.2s;">
                <div class="ps-grid-container">
                    <div class="ps-grid input-grid">
