                    <span class="ps-grid-label">H × W spatial tokens</span>
                </div>

                <div class="ps-arrow-section">
                    <span class="ps-arrow">⟶</span>
                    <span class="ps-arrow-label">Pixel Shuffle<br>r = 4</span>
                </div>

