         ========================================================= -->
    <section class="slide context-slide" data-slide="6">
        <div class="slide-content">
            <span class="tag reveal">Finding 2</span>
            <h2 class="reveal">Extending Context from 2K to 16K Tokens Unlocks Higher Resolution</h2>

            <div class="context-cards reveal" style="transition-delay: 0.2s;">
                <div class="context-card">
                    <span class="context-card-number">01</span>
                    <div class="context-card-title">RoPE Base Adjustment</div>
